function decode(s: string): PBar[] {
  const [head, body] = s.split('|');
  const [t0s, es] = head.split(',');
  const unit = Math.pow(10, Number(es));
  let t = parseInt(t0s, 36) * 86_400_000;
  return body.split(';').map((row) => {
    const [dt, o, h, l, c, v] = row.split(',');
    t += parseInt(dt, 36) * 86_400_000;
    const vv = parseInt(v, 36);
    return { t, o: parseInt(o, 36) * unit, h: parseInt(h, 36) * unit, l: parseInt(l, 36) * unit, c: parseInt(c, 36) * unit, v: vv ? Math.floor(vv / 20) * Math.pow(10, vv % 20) : NaN };
  });
}
/** current structures: the engine's hits plus a breakout the engine calls completed that is still recent (≤ 15 sessions / 3 weeks /
 *  2 months — the chart indicator's own rule, components/charts/pattern-view RECENT_BREAK_BARS) */
const RECENT: Record<PatternTimeframe, number> = { D: 15, W: 3, M: 2 };
function current(f: Fx): PatternHit[] {
  const a = analyzePatterns(decode(f.bars), { timeframe: f.tf, weak: true });
  const recent = (a.expired || []).filter((h) => h.expired === 'completed' && h.breakAgo != null && h.breakAgo <= RECENT[f.tf] && !a.hits.some((x) => x.id === h.id));
  return [...a.hits, ...recent];
}

test('zzz1014 audited misses are read now (each was missed by cp-3.3)', () => {
  const tps = FIX.filter((f) => f.kind === 'tp');
  assert.ok(tps.length >= 12);
  for (const f of tps) {
    const h = current(f).find((x) => x.id === f.id);
    assert.ok(h, `${f.name} (${f.why}) not read; got ${current(f).map((x) => x.id).join(',')}`);
    assert.ok(h.confidence >= 0.35, `${f.name}: ${h.confidence}`);
  }
});

test('zzz1014 relaxed rules still reject these readings', () => {
  for (const f of FIX.filter((x) => x.kind === 'fp')) {
    const h = current(f).find((x) => x.id === f.id);
    assert.equal(h, undefined, `${f.name} must not be reported (${f.why}); got ${h?.id}:${h?.confidence}`);
  }
});

test('zzz1014 flat bases: 15–20% deep only sideways or with the close in the upper half; a near-record lip ≤ 3% below the top', () => {
  assert.equal(FLAT_MAX_DEPTH, 0.2);
  assert.equal(NEAR_LIP, 0.03);
  for (const name of ['SKYGOLD D flat_base', 'FCX D flat_base', 'CGPOWER D flat_base']) {
    const f = FIX.find((x) => x.name === name)!;
    const h = current(f).find((x) => x.id === 'flat_base')!;
    assert.ok(h.depthPct! > 15 && h.depthPct! <= 20, `${name} depth ${h.depthPct}`);
    assert.ok(h.confidence < 0.75, `${name}: a 15–20% base never reads "very likely" (${h.confidence})`);
  }
  const t = current(FIX.find((x) => x.name === 'TDPOWERSYS W flat_base')!).find((x) => x.id === 'flat_base')!;
  const lip = t.points!.find((p) => p.role === 'LIP')!.p, top = t.points!.find((p) => p.role === 'R')!.p;
  assert.ok(top > lip && top <= lip * 1.03 && Math.abs(t.pivot! - top) < 0.01, `pivot = the base top (${lip} / ${top} / ${t.pivot})`);
});

test('zzz1014 a later base breakout is read at the bar it happened (AZAD daily)', () => {
  const f = FIX.find((x) => x.name === 'AZAD D flat_base')!;
  const h = current(f).find((x) => x.id === 'flat_base')!;
  assert.equal(h.stage, 'breakout');
  assert.ok(h.breakAgo != null && h.breakAgo <= 15 && h.breakAgo > stageWindowsFor('D').breakout, `breakAgo ${h.breakAgo}`);
});

test('zzz1014 monthly: reversals over up to 4 years, triangles / wedges still not applicable', () => {
  assert.equal(MONTHLY_REVERSAL_MAX, 48);
  for (const id of ['ascending_triangle', 'descending_triangle', 'falling_wedge', 'rising_wedge'] as PatternId[]) assert.equal(patternApplies(id, 'M'), false, id);
  const h = current(FIX.find((x) => x.name === 'RELIANCE M double_top')!).find((x) => x.id === 'double_top')!;
  const tops = h.points!.filter((p) => p.role === 'H1' || p.role === 'H2');
  assert.equal(tops.length, 2);
  assert.ok((tops[1].t - tops[0].t) / 86_400_000 > 480, 'tops more than 16 months apart');
});

test('zzz1014 version bumps', () => {
  assert.equal(PATTERN_ENGINE_VERSION, 'cp-3.4-recall');
  assert.equal(PATTERN_SCAN_VERSION, 10);
});
